def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(n, separators):
        result, start = [], 0
        for x in separators:
            if start < x:
                result.append(list(range(start, x)))
            start = x + 1
        if start < n:
            result.append(list(range(start, n)))
        return result

    row_groups = segments(h, sep_rows)
    col_groups = segments(w, sep_cols)
    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors.update(grid[0][c] for c in sep_cols)

    values = [grid[r][c] for r in range(h) for c in range(w)
              if r not in sep_rows and c not in sep_cols]
    background = max(set(values), key=values.count)

    best = None
    best_count = 0
    for ri, rows in enumerate(row_groups):
        for ci, cols in enumerate(col_groups):
            cells = [(r, c, grid[r][c]) for r in rows for c in cols
                     if grid[r][c] != background]
            if len(cells) > best_count:
                best, best_count = (ri, ci, cells), len(cells)

    out = [row[:] for row in grid]
    if best is None:
        return out
    _, _, cells = best
    source_r, source_c = row_groups[best[0]][0], col_groups[best[1]][0]
    pattern = [(r - source_r, c - source_c, color) for r, c, color in cells]

    for rows in row_groups:
        for cols in col_groups:
            for r in rows:
                for c in cols:
                    out[r][c] = background
            for dr, dc, color in pattern:
                if dr < len(rows) and dc < len(cols):
                    out[rows[dr]][cols[dc]] = color
    return out
